INSERT INTO `reviews` VALUES (1,1,NULL,'Nguyễn Hoàng Nam',5.0,'Sản phẩm chính hãng, màn hình OLED siêu đẹp, chơi game mượt mà cực kỳ thích! Giao hàng nhanh.','published','2026-07-27 17:23:01','2026-07-27 17:23:01'),(2,1,NULL,'Trần Minh Đức',4.5,'Thiết kế mỏng nhẹ tiện mang đi làm, hiệu năng i9 siêu mạnh nhưng máy hơi ấm lên khi chơi game nặng lâu.','published','2026-07-27 17:23:01','2026-07-27 17:23:01'),(3,13,NULL,'Lê Minh Quân',5.0,'Màn hình 120Hz mượt, phím bấm nhạy, Ally X dùng sướng hơn bản cũ nhiều, pin trâu hơn hẳn.','published','2026-07-27 17:23:01','2026-07-27 17:23:01'),(4,14,NULL,'Phan Mỹ Linh',5.0,'Máy ráp rất chắc chắn, chạy êm và chiến game AAA cực mượt.','published','2026-07-27 17:23:01','2026-07-27 17:23:01'),(5,15,NULL,'Hoàng Quốc Bảo',5.0,'Âm thanh vòm nghe tiếng chân địch trong game rất rõ, mic lọc âm tốt.','published','2026-07-27 17:23:01','2026-07-27 17:23:01'),(6,16,NULL,'Vũ Phương Anh',4.0,'Màn hình cong đẹp, tần số quét 165Hz chơi game mượt, tuy nhiên chân đế hơi to chiếm diện tích bàn.','published','2026-07-27 17:23:01','2026-07-27 17:23:01');
